#!/bin/bash
# TXE4-5 unit 5 (beside only): TXE3-10's owner-pool T18/T98 model (dev truth + secure + the owner's 4 Oct sort; the one arm
# allowed to read dev truth, per the brief) rebuilt on the MACHINE maps, on dev_tune (--loo-lines) and on f152r passZ
# (--exclude-pool-page f152r). The f152r run needs the dev-pool lines (no.87) and the applied lines (f152r) in one --map, so the
# two PASSed machine maps are concatenated; the concatenation has no sidecar of its own, hence --allow-unchecked-join (printed).
set -e; cd "$(git rev-parse --show-toplevel)"
python3 benchmark-tx/txeng4/5/scratch/tools/glyph_atlas.py classify --out ciphers/nevers-birago-fr3251-1572/atlas --pair T18 T98 --pool-dev benchmark-tx/txeng/units/labels_dev_tune.tsv --truth benchmark-tx/birago1572-no87.truth.tsv --pool-secure ciphers/nevers-birago-fr3251-1572/atlas/secure_tokens.tsv --pool-owner ciphers/nevers-birago-fr3251-1572/sorter/owner-sort-2026-10-04/settled_labels.tsv --owner-map ciphers/nevers-birago-fr3251-1572/sorter/no87/owner_map.tsv --exclude-pool-page f178r --exclude-pool-page f178v --exclude-pool-page f179r --exclude-pool-page f152r --map benchmark-tx/txeng4/5/maps/no87_labels.tsv --apply-unit benchmark-tx/txeng/units/labels_dev_tune.tsv --loo-lines --shuffle-lolo 20 --tsv benchmark-tx/txeng4/5/beside/owner_T18_T98_dev_tune.tsv --report benchmark-tx/txeng4/5/beside/owner_report_dev.tsv --touched benchmark-tx/txeng4/5/beside/owner_touched_dev.tsv
python3 benchmark-tx/txeng4/5/scratch/tools/glyph_atlas.py classify --out ciphers/nevers-birago-fr3251-1572/atlas --pair T18 T98 --pool-dev benchmark-tx/txeng/units/labels_dev_tune.tsv --truth benchmark-tx/birago1572-no87.truth.tsv --pool-secure ciphers/nevers-birago-fr3251-1572/atlas/secure_tokens.tsv --pool-owner ciphers/nevers-birago-fr3251-1572/sorter/owner-sort-2026-10-04/settled_labels.tsv --owner-map ciphers/nevers-birago-fr3251-1572/sorter/no87/owner_map.tsv --exclude-pool-page f178r --exclude-pool-page f178v --exclude-pool-page f179r --exclude-pool-page f152r --map benchmark-tx/txeng4/5/beside/map_no87L_f152rZ_concat.tsv --allow-unchecked-join 'concatenation of two join_check-PASSed machine maps (maps/no87_labels.tsv + maps/f152r_passZ.tsv), beside arm only' --apply-unit benchmark-tx/outputs/birago1572-f152r/passZ_pipeline.tsv --tsv benchmark-tx/txeng4/5/beside/owner_T18_T98_f152r_passZ.tsv --report benchmark-tx/txeng4/5/beside/owner_report_f152r.tsv --touched benchmark-tx/txeng4/5/beside/owner_touched_f152r.tsv
